// --- Sub-Component: Copy Field ---
const CopyInput = ({ label, value }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(value);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className='copy-input-container'>
      <label className='input-label'>{label}</label>
      <div className='input-wrapper'>
        <code className='code-display'>{value || "Waiting for file..."}</code>
        <button onClick={handleCopy} disabled={!value} className='btn-icon'>
          {copied ? <IconCheck /> : <IconCopy />}
        </button>
      </div>
    </div>
  );
};

// --- Sub-Component: Copyable Table Cell ---
const CopyCell = ({ value }) => {
  const [copied, setCopied] = useState(false);

  const copy = () => {
    navigator.clipboard.writeText(value);
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  };

  return (
    <div className='input-wrapper'>
      <code className='code-display'>{value}</code>
      <button className='btn-icon' onClick={copy}>
        {copied ? <IconCheck /> : <IconCopy />}
      </button>
    </div>
  );
};

// --- Main App Component ---
function App() {
  const [fileData, setFileData] = useState([]);
  const [headers, setHeaders] = useState([]);
  const [fileName, setFileName] = useState("");

  const [deviceId, setDeviceId] = useState("");
  const [deviceHash, setDeviceHash] = useState("");

  const [separator, setSeparator] = useState(",");
  const [hasHeaders, setHasHeaders] = useState(true);
  const [showAdvanced, setShowAdvanced] = useState(false);

  const fileInputRef = useRef(null);

  // --- Load saved devices from localStorage ---
  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem("savedDevices") || "[]");
    if (saved.length > 0) {
      setFileData(saved);
      setHeaders(["Device ID", "Device Hash"]);
    }
  }, []);

  const calculateHash = async text => {
    const encoder = new TextEncoder();
    const data = encoder.encode(text);
    const hashBuffer = await crypto.subtle.digest("SHA-256", data);
    return Array.from(new Uint8Array(hashBuffer))
      .map(b => b.toString(16).padStart(2, "0"))
      .join("");
  };

  const generateDeviceId = () => "dev_" + crypto.randomUUID().replace(/-/g, "").slice(0, 16);

  const saveDeviceLocally = (id, hash) => {
    const newEntry = { id, hash };
    const existing = JSON.parse(localStorage.getItem("savedDevices") || "[]");
    const updated = [newEntry, ...existing]; // prepend newest first
    localStorage.setItem("savedDevices", JSON.stringify(updated));
    setFileData(updated);
    setHeaders(["Device ID", "Device Hash"]);
  };

  const processFile = async file => {
    if (!file) return;

    setFileName(file.name);

    const text = await file.text();
    const hash = await calculateHash(text);
    const id = generateDeviceId();

    setDeviceHash(hash);
    setDeviceId(id);

    saveDeviceLocally(id, hash);
  };

  const resetAll = () => {
    localStorage.removeItem("savedDevices");
    setFileData([]);
    setHeaders([]);
    setFileName("");
    setDeviceId("");
    setDeviceHash("");
  };

  return (
    <div className='app-container'>
      <nav className='navbar'>
        <div className='nav-brand'>
          <img
            src='https://www.conectys.com/wp-content/uploads/2024/08/conectys-logo.svg'
            alt='Conectys Logo'
            className='logo-box'
            style={{
              width: "120px",
              height: "auto",
              display: "block",
            }}
          />
          <span className='brand-text'>CSV Viewer</span>
        </div>
      </nav>

      <main className='main-content'>
        <section className='card settings-card'>
          <div className='card-header clickable' onClick={() => setShowAdvanced(!showAdvanced)}>
            <IconSettings />
            <h2>CSV Settings</h2>
          </div>

          {showAdvanced && (
            <div className='settings-body show'>
              <select value={separator} onChange={e => setSeparator(e.target.value)}>
                <option value=','>Comma (,)</option>
                <option value=';'>Semi-colon (;)</option>
                <option value='|'>Bar (|)</option>
                <option value='\t'>Tab</option>
              </select>

              <label>
                <input type='checkbox' checked={hasHeaders} onChange={e => setHasHeaders(e.target.checked)} /> First row contains headers
              </label>

              <button className='btn-link-danger' onClick={resetAll}>
                Reset
              </button>
            </div>
          )}
        </section>

        {fileName && (
          <section className='card device-card'>
            <div className='card-header dark-header'>
              <h3>Device Identity Generated</h3>
              <span className='file-badge'>{fileName}</span>
            </div>
            <div className='device-grid'>
              <CopyInput label='Device ID' value={deviceId} />
              <CopyInput label='Device Hash (SHA-256)' value={deviceHash} />
            </div>
          </section>
        )}

        {!fileName && (
          <div className='upload-area' onClick={() => fileInputRef.current.click()}>
            <input ref={fileInputRef} type='file' accept='.csv' hidden onChange={e => processFile(e.target.files[0])} />
            <IconUpload />
            <h3>Select .csv files</h3>
          </div>
        )}

        {fileData.length > 0 && (
          <div className='card table-card'>
            <table className='csv-table'>
              <thead>
                <tr>
                  <th>#</th>
                  {headers.map((h, i) => (
                    <th key={i}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {fileData.map((row, r) => (
                  <tr key={r}>
                    <td className='index-col'>{r + 1}</td>
                    <td>
                      <CopyCell value={row.id} />
                    </td>
                    <td>
                      <CopyCell value={row.hash} />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </main>

      <footer className='footer'>
        <p>&copy; 2026 CVS Viewer. Open Source.</p>
      </footer>
    </div>
  );
}

export default App;
